<?php
declare(strict_types=1);
require_once __DIR__.'/support/enrollment_fixture.php';
require_once __DIR__.'/support/enrollment_app_fixture.php';
require_once dirname(__DIR__).'/includes/attendance_decisions.php';
checkEnrollment(function_exists('deleteDeliveryMode'),'Delivery entries must have a protected delete service');
withEnrollmentFixture(function(array $f): void {
    $db=$f['db']; ensureDeliverySchema($db); ensureAttendanceDecisionSchema($db);
    $db->exec("INSERT INTO system_settings(setting_key,setting_value) VALUES('enrollment_model_version','1'); INSERT INTO users(id,username,password,full_name,role) VALUES(9,'fixture_scanner','unused','Synthetic Scanner','scanner_operator'); UPDATE users SET session_token=CONCAT('synthetic-fixture-session-',id)");
    $insert=function(int $section,string $date,string $mode='modular')use($db):int {
        $q=$db->prepare('INSERT INTO delivery_modes(school_year_id,scope_section_id,learning_date,mode,deadline_at,recorded_by) VALUES(1,?,?,?,?,1)');
        $q->execute([$section,$date,$mode,$mode==='modular'?'2026-10-30 13:00:00':null]); return (int)$db->lastInsertId();
    };
    $school=$insert(0,'2026-10-13','online'); $own=$insert(10,'2026-10-13');
    $foreign=$insert(11,'2026-10-13');
    $preview=deleteDeliveryMode($db,$f['teacher'],['id'=>$own]);
    checkEnrollment(!$preview['deleted'] && str_contains($preview['fallback_message'],'Online'),'Deleting a section override previews the inherited school mode');
    checkEnrollment((int)$db->query('SELECT COUNT(*) FROM delivery_modes')->fetchColumn()===3,'Delete preview performs no writes');
    expectEnrollmentError(DomainException::class,fn()=>deleteDeliveryMode($db,$f['teacher'],['id'=>$school]));
    expectEnrollmentError(DomainException::class,fn()=>deleteDeliveryMode($db,$f['teacher'],['id'=>$foreign]));
    expectEnrollmentError(DomainException::class,fn()=>deleteDeliveryMode($db,['id'=>7,'role'=>'admin'],['id'=>$school]));
    $db->exec("UPDATE delivery_modes SET mode='face_to_face',revision=revision+1 WHERE id=$school");
    $stale=deleteDeliveryMode($db,$f['teacher'],['id'=>$own,'confirm_token'=>$preview['token']]);
    checkEnrollment(!$stale['deleted'] && str_contains($stale['fallback_message'],'Face-to-face'),'Changed inheritance invalidates delete confirmation');
    $saved=deleteDeliveryMode($db,$f['teacher'],['id'=>$own,'confirm_token'=>$stale['token']]);
    checkEnrollment($saved['deleted'] && resolveDeliveryDay($db,1,10,'2026-10-13')['mode']==='face_to_face','Confirmed delete removes only the override and restores inherited mode');
    checkEnrollment((int)$db->query('SELECT COUNT(*) FROM delivery_modes')->fetchColumn()===2,'Unrelated schedules remain');
    checkEnrollment((int)$db->query("SELECT COUNT(*) FROM security_events WHERE action='delivery.delete'")->fetchColumn()===1,'Deletion is audited');
    expectEnrollmentError(DomainException::class,fn()=>deleteDeliveryMode($db,$f['teacher'],['id'=>$own,'confirm_token'=>$stale['token']]));
    $preview=deleteDeliveryMode($db,$f['admin'],['id'=>$school]);
    checkEnrollment(str_contains($preview['fallback_message'],'overrides'),'Whole-school delete explains preservation of section overrides');
    deleteDeliveryMode($db,$f['admin'],['id'=>$school,'confirm_token'=>$preview['token']]);
    checkEnrollment(resolveDeliveryDay($db,1,11,'2026-10-13')['mode']==='modular','Whole-school removal preserves section overrides');
    $closed=$insert(0,'2026-10-14');
    $db->exec("INSERT INTO school_calendar(date,title,type) VALUES('2026-10-14','Synthetic closure','no_class')");
    $preview=deleteDeliveryMode($db,$f['admin'],['id'=>$closed]);
    checkEnrollment(str_contains($preview['fallback_message'],'No class'),'Inactive saved schedule previews the retained closure');
    deleteDeliveryMode($db,$f['admin'],['id'=>$closed,'confirm_token'=>$preview['token']]);
    checkEnrollment(!resolveDeliveryDay($db,1,10,'2026-10-14')['eligible'],'Deleting a delivery schedule never deletes its closure');
    $recorded=$insert(10,'2026-10-21');
    expectEnrollmentError(DomainException::class,fn()=>deleteDeliveryMode($db,$f['admin'],['id'=>$recorded]));
    $decision=$insert(0,'2026-10-19');
    $db->exec("INSERT INTO attendance_decisions(enrollment_id,assignment_id,learning_date,decision,delivery_mode,recorded_by,confirmed_at) VALUES(1001,2001,'2026-10-19','pending','modular',7,'2026-10-19 08:00:00'); UPDATE sections SET is_active=0 WHERE id=10");
    expectEnrollmentError(DomainException::class,fn()=>deleteDeliveryMode($db,$f['admin'],['id'=>$decision]));
    $db->exec('UPDATE sections SET is_active=1 WHERE id=10');
    $legacy=$insert(0,'2026-10-22');
    $db->exec("INSERT INTO attendance(student_id,date,attendance_type,recorded_by) VALUES(101,'2026-10-22','absent',7)");
    expectEnrollmentError(DomainException::class,fn()=>deleteDeliveryMode($db,$f['admin'],['id'=>$legacy]));
    $legacySection=$insert(11,'2026-10-22');
    expectEnrollmentError(DomainException::class,fn()=>deleteDeliveryMode($db,$f['admin'],['id'=>$legacySection]));
    $raced=$insert(10,'2026-10-16'); $p=deleteDeliveryMode($db,$f['teacher'],['id'=>$raced]);
    $db->exec("INSERT INTO attendance_decisions(enrollment_id,assignment_id,learning_date,decision,delivery_mode,recorded_by,confirmed_at) VALUES(1001,2001,'2026-10-16','pending','modular',7,'2026-10-16 08:00:00')");
    expectEnrollmentError(DomainException::class,fn()=>deleteDeliveryMode($db,$f['teacher'],['id'=>$raced,'confirm_token'=>$p['token']]));
    checkEnrollment((int)$db->query("SELECT COUNT(*) FROM delivery_modes WHERE id=$raced")->fetchColumn()===1,'A decision recorded after preview prevents deletion');
    $copy=__DIR__.'/enrollment_app_'.bin2hex(random_bytes(8)); createEnrollmentAppFixture($copy);
    try {
        $run=fn($actor,$post=[])=>runEnrollmentAppEndpoint($copy,$f,'calendar/calendar.php',$actor,$post,['month'=>10,'year'=>2026],$post?'POST':'GET');
        $json=fn($r)=>json_decode(preg_replace('/\nRESULT:.*$/s','',$r['body']),true,512,JSON_THROW_ON_ERROR);
        $candidate=$insert(10,'2026-10-15');
        file_put_contents(dirname(__DIR__).'/.qa/delivery-delete.html',$run($f['admin'])['body']);
        $html=$run($f['teacher'])['body'];
        $doc=new DOMDocument(); @$doc->loadHTML($html); $xp=new DOMXPath($doc);
        checkEnrollment($xp->query('//*[@data-delivery-id="'.$candidate.'"]')->length===1,'Teacher sees a trash action for their delivery entry');
        checkEnrollment($xp->query('//*[@data-delivery-id="'.$foreign.'"]')->length===0,'Teacher cannot see another section delete action');
        $listing=runEnrollmentAppEndpoint($copy,$f,'calendar/delivery_modes.php',$f['admin'],[],[],'GET');
        $doc=new DOMDocument(); @$doc->loadHTML($listing['body']); $xp=new DOMXPath($doc);
        checkEnrollment($xp->query('//*[@data-delivery-id="'.$foreign.'"]')->length===1,'Scheduled-date list also offers delivery deletion');
        $post=['ajax'=>'1','action'=>'delivery_delete','id'=>$candidate];
        checkEnrollment($run($f['teacher'],$post+['csrf_token'=>'invalid'])['status']===403,'Delete endpoint requires valid CSRF');
        checkEnrollment(in_array($run(['id'=>9,'role'=>'scanner_operator'],$post)['status'],[302,403],true),'Scanner operators cannot delete delivery entries');
        $p=$json($run($f['teacher'],$post));
        checkEnrollment($p['success'] && !$p['deleted'],'AJAX first previews without deleting');
        $r=$json($run($f['teacher'],$post+['confirm_token'=>$p['token']]));
        checkEnrollment($r['success'] && $r['deleted'],'AJAX confirmed deletion succeeds');
        checkEnrollment(!$json($run($f['teacher'],['ajax'=>'1','action'=>'delivery_delete','id'=>$foreign]))['success'],'Guessed foreign entry ID is rejected');
        checkEnrollment(!is_file($copy.'/provider-calls.log'),'Deleting delivery entries sends no messages');
    } finally { removeEnrollmentAppFixture($copy); removeEnrollmentAppFixturePhotos($copy); }
    $p=deleteDeliveryMode($db,$f['admin'],['id'=>$foreign]);
    $db->exec("UPDATE school_years SET state='closed' WHERE id=1");
    expectEnrollmentError(DomainException::class,fn()=>deleteDeliveryMode($db,$f['admin'],['id'=>$foreign,'confirm_token'=>$p['token']]));
});
echo 'Delivery deletion passed ('.$GLOBALS['enrollment_checks']." checks).\n";
